#!/usr/bin/env python3
"""Add staleness results to reports generated by vexscan-dashboard.py.

The upstream renderer has no knowledge of scan.sh's staleness field. This
post-processing pass adds the complete result set to the fleet index and a
small warning banner to each flagged image page. Unknown page mappings are
skipped with a warning rather than guessed.
"""
import html
import json
import os
import re
import sys

BANNER_MARKER = "banner-staleness"
INDEX_MARKER = "staleness-summary"
EXCULPATORY = ("not_affected", "fixed")


def esc(value):
    return html.escape(str(value), quote=True)


def load_report(json_path):
    with open(json_path, "r", encoding="utf-8") as fh:
        return json.load(fh)


def load_staleness_images(doc):
    images = (doc.get("staleness") or {}).get("images") or []
    return images


def build_target_href_map(run_index_path):
    """Map each target's exact image ref (as rendered by vexscan-dashboard.py)
    to its per-image page's href, by reading that run's own index page -
    avoids having to reimplement vexscan-dashboard.py's filename slugging."""
    with open(run_index_path, "r", encoding="utf-8") as fh:
        content = fh.read()
    mapping = {}
    for m in re.finditer(r'<a href="([^"]+\.html)"[^>]*>([^<]+)</a>', content):
        href, target = m.group(1), html.unescape(m.group(2)).strip()
        mapping[target] = href
    return mapping


def render_banner(img):
    findings_current = img.get("findings_current")
    findings_latest = img.get("findings_latest")
    delta = None
    if findings_current is not None and findings_latest is not None:
        delta = sum(findings_current.values()) - sum(findings_latest.values())

    name = img.get("image_name") or img.get("image") or "this image"
    latest_tag = img.get("latest_tag") or "a newer tag"
    text = "A newer tag is available: %s %s" % (esc(name), esc(latest_tag))
    if delta is not None and delta > 0:
        text += " &mdash; fixes %d additional CVE%s" % (delta, "" if delta == 1 else "s")
    text += (
        '. See the <a href="index.html#%s">image update comparison</a>.'
        % esc(INDEX_MARKER)
    )
    return (
        '<div class="banner banner-warn %s"><span class="icon">&#9888;</span>'
        "<span>%s</span></div>"
    ) % (BANNER_MARKER, text)


def inject(page_path, banner_html):
    with open(page_path, "r", encoding="utf-8") as fh:
        content = fh.read()
    if BANNER_MARKER in content:
        return False  # already injected; keep re-runs idempotent

    idx = content.find('<div class="banner')
    if idx == -1:
        idx = content.find("</main>")
    if idx == -1:
        return False

    content = content[:idx] + banner_html + content[idx:]
    with open(page_path, "w", encoding="utf-8") as fh:
        fh.write(content)
    return True


def affected_findings(doc):
    total = 0
    for result in doc.get("results") or []:
        for finding in result.get("findings") or []:
            if finding.get("status") not in ("linked", "reachable"):
                continue
            if (finding.get("vex") or {}).get("status") not in EXCULPATORY:
                total += 1
    return total


def finding_total(counts):
    if counts is None:
        return None
    return sum(counts.values())


def render_index_summary(doc, target_href):
    staleness = doc.get("staleness") or {}
    images = staleness.get("images") or []
    if not images:
        return ""

    summary = staleness.get("summary") or {}
    compared = [
        img for img in images
        if img.get("status") == "NEEDS_UPDATE"
        and img.get("findings_current") is not None
        and img.get("findings_latest") is not None
    ]
    current_fleet = affected_findings(doc)
    delta = sum(
        finding_total(img["findings_current"]) - finding_total(img["findings_latest"])
        for img in compared
    )
    compared_text = "%d of %d updates rescanned" % (
        len(compared), summary.get("needs_update", 0))
    if compared:
        projected = current_fleet - delta
        fleet_text = "Fleet affected findings: %d &#8594; %d" % (
            current_fleet, projected)
        if len(compared) < summary.get("needs_update", 0):
            fleet_text += " (partial comparison)"
    else:
        fleet_text = "Fleet projection unavailable"

    rows = []
    for img in images:
        target = img.get("image") or ""
        href = target_href.get(target)
        name = img.get("image_name") or target or "?"
        image_cell = (
            '<a href="%s"><code>%s</code></a>' % (esc(href), esc(name))
            if href else '<code>%s</code>' % esc(name)
        )
        current_tag = img.get("current_tag") or "?"
        latest_tag = img.get("latest_tag") or "unavailable"
        status = img.get("status") or "UNKNOWN"
        current = finding_total(img.get("findings_current"))
        latest = finding_total(img.get("findings_latest"))
        counts = (
            "%d &#8594; %d" % (current, latest)
            if current is not None and latest is not None
            else "unavailable"
        )
        if current is not None and latest is not None:
            change = current - latest
            if change > 0:
                change_text = "%d fewer" % change
            elif change < 0:
                change_text = "%d more" % -change
            else:
                change_text = "no change"
        else:
            change_text = "unknown"
        rows.append(
            '<tr><td>%s</td><td class="mono nowrap">%s &#8594; %s</td>'
            '<td><span class="staleness-status staleness-%s">%s</span></td>'
            '<td class="num">%s</td><td class="nowrap">%s</td></tr>'
            % (
                image_cell,
                esc(current_tag),
                esc(latest_tag),
                esc(status.lower().replace("_", "-")),
                esc(status.replace("_", " ")),
                counts,
                esc(change_text),
            )
        )

    return """
<section id="%(marker)s" class="staleness-summary">
  <style>
    .staleness-summary { margin-bottom: 24px; }
    .staleness-summary h2 { margin-bottom: 8px; }
    .staleness-summary .staleness-lead {
      display: flex; flex-wrap: wrap; gap: 6px 18px;
      margin-bottom: 10px; color: var(--muted); font-size: 13px;
    }
    .staleness-summary .staleness-status {
      display: inline-block; border: 1px solid var(--border);
      border-radius: 999px; padding: 1px 7px; font-size: 11px;
      font-weight: 600; white-space: nowrap;
    }
    .staleness-needs-update { color: #7A5C00; background: #FFF7E8; border-color: var(--sev-medium-border) !important; }
    .staleness-up-to-date { color: #1A7A41; background: #EAF7EF; border-color: var(--ok-border) !important; }
    .staleness-unknown { color: var(--muted); background: var(--box-bg); }
    :root[data-theme="dark"] .staleness-needs-update { color: #E0B84D; background: #241F14; }
    :root[data-theme="dark"] .staleness-up-to-date { color: #5FCF8C; background: #15291E; }
  </style>
  <h2 class="anchored">Image update comparison <a class="anchor" href="#%(marker)s">#</a></h2>
  <div class="staleness-lead">
    <strong>%(fleet_text)s</strong>
    <span>%(needs_update)d images need updates · %(up_to_date)d up to date · %(unknown)d unknown</span>
    <span>%(compared_text)s</span>
  </div>
  <div class="panel table-wrap">
    <table class="report-table">
      <thead><tr><th>Image</th><th>Tag change</th><th>Status</th><th class="num">Affected findings</th><th>Change</th></tr></thead>
      <tbody>%(rows)s</tbody>
    </table>
  </div>
</section>
""" % {
        "marker": INDEX_MARKER,
        "fleet_text": fleet_text,
        "needs_update": summary.get("needs_update", 0),
        "up_to_date": summary.get("up_to_date", 0),
        "unknown": summary.get("unknown", 0),
        "compared_text": compared_text,
        "rows": "".join(rows),
    }


def inject_index_summary(index_path, summary_html):
    with open(index_path, "r", encoding="utf-8") as fh:
        content = fh.read()
    if INDEX_MARKER in content:
        return False
    marker = '<main class="page-content">'
    idx = content.find(marker)
    if idx == -1:
        return False
    idx += len(marker)
    content = content[:idx] + summary_html + content[idx:]
    with open(index_path, "w", encoding="utf-8") as fh:
        fh.write(content)
    return True


def main():
    if len(sys.argv) != 4:
        print(
            "usage: inject_staleness_banners.py <scan.json> <run-html-dir> <scan-id>",
            file=sys.stderr,
        )
        return 1
    json_path, run_html_dir, scan_id = sys.argv[1:4]

    try:
        doc = load_report(json_path)
        images = load_staleness_images(doc)
    except (OSError, ValueError) as exc:
        print(
            "Warning: could not read staleness data from %s (%s); skipping banner injection"
            % (json_path, exc),
            file=sys.stderr,
        )
        return 0
    if not images:
        return 0

    run_index_path = os.path.join(run_html_dir, "index.html")
    try:
        target_href = build_target_href_map(run_index_path)
    except OSError as exc:
        print(
            "Warning: could not read %s (%s); skipping banner injection" % (run_index_path, exc),
            file=sys.stderr,
        )
        return 0

    summary_html = render_index_summary(doc, target_href)
    if not inject_index_summary(run_index_path, summary_html):
        with open(run_index_path, "r", encoding="utf-8") as fh:
            if INDEX_MARKER not in fh.read():
                print("Warning: could not inject staleness summary into %s"
                      % run_index_path)

    stale_images = [img for img in images if img.get("status") == "NEEDS_UPDATE"]
    injected = 0
    for img in stale_images:
        target = img.get("image")
        href = target_href.get(target)
        if not href:
            print(
                "Warning: no rendered page found for stale image %s; skipping its banner" % target,
                file=sys.stderr,
            )
            continue
        page_path = os.path.join(run_html_dir, href)
        banner_html = render_banner(img)
        try:
            if inject(page_path, banner_html):
                injected += 1
        except OSError as exc:
            print("Warning: could not inject banner into %s (%s)" % (page_path, exc), file=sys.stderr)

    print("Injected fleet update summary and staleness banners into %d page(s)" % injected)
    return 0


if __name__ == "__main__":
    sys.exit(main())
